/* UI state and operations for the solver and extra graph modes. */
static int fieldCount(void){return solverKind==0?polyDegree+1:solverKind==1?3:solverKind==2?solverN:4;}
static const char*kindName(void){return solverKind==0?tr("Polinómio · raízes reais/complexas","Polynomial · real/complex roots"):solverKind==1?tr("Equação · pesquisa num intervalo","Equation · interval search"):solverKind==2?tr("Sistema linear","Linear system"):tr("Sistema não linear · solução numérica","Nonlinear system · numerical solution");}
static const char*fieldName(int i,char*b,size_t n){if(solverKind==0){snprintf(b,n,tr("Coeficiente de X^%d","Coefficient of X^%d"),polyDegree-i);return b;}if(solverKind==1)return i==0?tr("Equação em X","Equation in X"):i==1?tr("X mínimo","X minimum"):tr("X máximo","X maximum");if(solverKind==2||i<2){snprintf(b,n,tr("Equação %d","Equation %d"),i+1);return b;}return i==2?tr("X inicial","Initial X"):tr("Y inicial","Initial Y");}
static void saveAdvanced(void){if(!*advancedpath)return;char tmp[4100];snprintf(tmp,sizeof(tmp),"%s.new",advancedpath);FILE*f=fopen(tmp,"w");if(!f)return;fputs("BAETACALC_ADV_V1\n",f);for(int i=0;i<6;i++)fprintf(f,"%d\n%d\n",curveType[i],shadeSide[i]);fprintf(f,"%d\n%d\n%d\n",polyDegree,solverKind,solverN);for(int k=0;k<4;k++)for(int i=0;i<7;i++)fprintf(f,"%s\n",solverFields[k][i]);if(fclose(f)==0)rename(tmp,advancedpath);}
static int readNumber(FILE*f,int lo,int hi,int fallback){char b[64];if(!fgets(b,sizeof(b),f))return fallback;char*end;long n=strtol(b,&end,10);return end!=b&&n>=lo&&n<=hi?(int)n:fallback;}
static void loadAdvanced(void){FILE*f=fopen(advancedpath,"r");if(!f)return;char b[600];if(!fgets(b,sizeof(b),f)||strcmp(b,"BAETACALC_ADV_V1\n")){fclose(f);return;}for(int i=0;i<6;i++){curveType[i]=readNumber(f,0,2,0);shadeSide[i]=readNumber(f,-1,1,0);}polyDegree=readNumber(f,1,6,2);solverKind=readNumber(f,0,3,0);solverN=readNumber(f,2,3,2);for(int k=0;k<4;k++)for(int i=0;i<7;i++)if(fgets(b,sizeof(b),f)){b[strcspn(b,"\r\n")]=0;snprintf(solverFields[k][i],512,"%.511s",b);}fclose(f);}
static int scalar(const char*s,double*out){return evaluateXYZ(s,0,0,0,ans,deg,0,out);}
static void solveUI(void){solverStatus=0;resultPage=0;rootCount=realCount=0;int ok=0;if(solverKind==0){for(int i=0;i<=polyDegree;i++)if(!scalar(solverFields[0][i],&polyCoefficients[i])){solverStatus=9;return;}ok=polynomialRoots(polyCoefficients,polyDegree,complexRoots,&rootCount);solverStatus=ok==1?1:ok==2?3:ok==0?2:10;}
 else if(solverKind==1){double lo,hi;if(!scalar(solverFields[1][1],&lo)||!scalar(solverFields[1][2],&hi)){solverStatus=9;return;}ok=realRoots(solverFields[1][0],lo,hi,ans,deg,realSolutions,&realCount);solverStatus=ok<0?9:realCount?8:11;}
 else if(solverKind==2){const char*eq[3]={solverFields[2][0],solverFields[2][1],solverFields[2][2]};ok=solveLinear(eq,solverN,ans,deg,systemSolution,systemRows);solverStatus=ok==1?4:ok==2?5:ok==0?6:9;}
 else{double x,y;if(!scalar(solverFields[3][2],&x)||!scalar(solverFields[3][3],&y)){solverStatus=9;return;}ok=nonlinearSystem(solverFields[3][0],solverFields[3][1],x,y,ans,deg,systemSolution);solverStatus=ok?7:10;}
 save();}
static void solverExample(void){solverStatus=0;solverField=0;if(solverKind==0){polyDegree=2;strcpy(solverFields[0][0],"1");strcpy(solverFields[0][1],"-3");strcpy(solverFields[0][2],"2");}else if(solverKind==1){strcpy(solverFields[1][0],"X^2-4=0");strcpy(solverFields[1][1],"-5");strcpy(solverFields[1][2],"5");}else if(solverKind==2){solverN=2;strcpy(solverFields[2][0],"2X+Y=-9");strcpy(solverFields[2][1],"Y=2X");strcpy(solverFields[2][2],"Z=1");}else{strcpy(solverFields[3][0],"X^2+Y^2=1");strcpy(solverFields[3][1],"Y=X");strcpy(solverFields[3][2],"1");strcpy(solverFields[3][3],"1");}cursor=strlen(active());save();}
static int differenceExpression(const char*eq,char*out,size_t size){const char*p=strchr(eq,'=');int n;if(p)n=snprintf(out,size,"(%.*s)-(%s)",(int)(p-eq),eq,p+1);else n=snprintf(out,size,"%s",eq);return n>=0&&(size_t)n<size;}
static void plotSolver(void){if(solverStatus!=1&&solverStatus!=4&&solverStatus!=7&&solverStatus!=8){showMessage("Resolva primeiro uma equação válida","Solve a valid equation first",0);return;}if(solverKind==2&&solverN==3){showMessage("Gráfico 2D: use um sistema de duas variáveis","2D graph: use a two-variable system",0);return;}
 memset(plotFields,0,sizeof(plotFields));memset(plotLabels,0,sizeof(plotLabels));memset(plotShade,0,sizeof(plotShade));memset(plotTypes,0,sizeof(plotTypes));markerCount=0;if(solverKind==0){size_t used=0;for(int i=0;i<=polyDegree;i++){int n=snprintf(plotFields[0]+used,512-used,"%s(%.14g)*X^%d",i?"+":"",polyCoefficients[i],polyDegree-i);if(n<0||(size_t)n>=512-used){solverStatus=9;return;}used+=n;}for(int i=0;i<rootCount;i++)if(fabs(cimag(complexRoots[i]))<1e-7&&markerCount<MAX_ROOTS){markerX[markerCount]=creal(complexRoots[i]);markerY[markerCount++]=0;}}
 else if(solverKind==1){if(!differenceExpression(solverFields[1][0],plotFields[0],512)){solverStatus=9;return;}for(int i=0;i<realCount;i++){markerX[i]=realSolutions[i];markerY[i]=0;}markerCount=realCount;}
 else if(solverKind==2){for(int i=0;i<2;i++){Affine a=systemRows[i];if(fabs(a.a[2])>1e-14)snprintf(plotFields[i],512,"(%.14g-(%.14g)*X)/(%.14g)",-a.a[0],a.a[1],a.a[2]);else{plotTypes[i]=1;snprintf(plotFields[i],512,"%.14g",-a.a[0]/a.a[1]);}}markerCount=1;markerX[0]=systemSolution[0];markerY[0]=systemSolution[1];}
 else{for(int i=0;i<2;i++){snprintf(plotFields[i],512,"%s",solverFields[3][i]);plotTypes[i]=2;}markerCount=1;markerX[0]=systemSolution[0];markerY[0]=systemSolution[1];}
 if(solverKind>=2){for(int i=0;i<2;i++)snprintf(plotLabels[i],512,"%s",solverFields[solverKind][i]);}else if(solverKind==1)snprintf(plotLabels[0],512,"%s",solverFields[1][0]);
 if(solverKind>=2){xmin=systemSolution[0]-5;xmax=systemSolution[0]+5;ymin=systemSolution[1]-5;ymax=systemSolution[1]+5;}
 else{double lo=-5,hi=5;if(markerCount){lo=hi=markerX[0];for(int i=1;i<markerCount;i++){lo=fmin(lo,markerX[i]);hi=fmax(hi,markerX[i]);}double margin=fmax(1,(hi-lo)*.3);lo-=margin;hi+=margin;}if(solverKind==1){scalar(solverFields[1][1],&lo);scalar(solverFields[1][2],&hi);}xmin=lo;xmax=hi;double low=0,high=0;for(int i=0;i<=100;i++){double v,x=lo+(hi-lo)*i/100;if(evaluate84(plotFields[0],x,ans,deg,&v)&&fabs(v)<1e6){low=fmin(low,v);high=fmax(high,v);}}double m=fmax(1,(high-low)*.15);ymin=low-m;ymax=high+m;}
 solverPlot=1;mode=2;setting=-1;target=0;tx=(xmin+xmax)/2;clearMessage();}
static void rootsSelected(void){if(curveType[target]!=0||!*ys[target]){showMessage("Selecione uma função Y= válida","Select a valid Y= function",0);return;}solverKind=1;solverField=0;snprintf(solverFields[1][0],512,"%s",ys[target]);snprintf(solverFields[1][1],512,"%.12g",xmin);snprintf(solverFields[1][2],512,"%.12g",xmax);mode=4;scientific=1;keyPage=2;cursor=strlen(active());solveUI();}
static void extraAction(int k){if(k==78){mode=4;setting=-1;scientific=1;keyPage=2;solverField=0;cursor=strlen(active());return;}if(k==79||k==80||k==81){keyPage=(keyPage+(k==79?2:1))%3;selected=0;return;}if(k==60){mode=1;setting=-1;solverPlot=0;int old=curveType[target];curveType[target]=old==0?1:0;for(char*p=ys[target];*p;p++)if((*p=='X'||*p=='x'||*p=='Y'||*p=='y')&&(p==ys[target]||!isalpha((unsigned char)p[-1]))&&!isalpha((unsigned char)p[1]))*p=curveType[target]?'Y':'X';cursor=strlen(active());save();return;}if(k==64){mode=1;setting=-1;solverPlot=0;shadeSide[target]=shadeSide[target]==0?-1:shadeSide[target]==-1?1:0;save();return;}if(k==71){mode=4;setting=-1;scientific=1;solverKind=(solverKind+1)%4;solverField=0;solverStatus=0;cursor=strlen(active());save();return;}if(k==72||k==77){solverField=(solverField+(k==77?fieldCount()-1:1))%fieldCount();cursor=strlen(active());return;}if(k==73){if(mode==4)solveUI();else rootsSelected();return;}if(k==74){plotSolver();return;}if(k==75){if(mode==4)solverExample();else showMessage("Abra SOLVER para usar o exemplo","Open SOLVER to use the example",0);return;}if(k==76){if(solverKind==0){polyDegree=polyDegree%6+1;for(int i=0;i<7;i++)strcpy(solverFields[0][i],"0");strcpy(solverFields[0][0],"1");strcpy(solverFields[0][polyDegree],"-1");}else if(solverKind==2)solverN=solverN==2?3:2;solverField=solverKind==1?1:solverKind==3?2:0;solverStatus=0;cursor=strlen(active());save();return;}}
